/* prog22_snake_camel_convert – reconstructed from the obfuscated binary
 *
 * The original program accepts three command‑line arguments:
 *   prog22_snake_camel_convert <mode> <string>
 *
 *   <mode>   – either "to_camel" or "to_snake"
 *   <string> – the text to be converted
 *
 * It prints the converted string on stdout.  If the number of arguments is
 * insufficient it prints "USAGE".  If the mode is not one of the two supported
 * strings it prints "INVALID_MODE".
 *
 * The conversion rules (deduced from the state‑machine in the binary):
 *
 *   to_camel :  snake_case  →  camelCase
 *       – underscores are removed.
 *       – the character following an underscore is upper‑cased.
 *       – all other alphabetic characters are forced to lower‑case.
 *
 *   to_snake :  camelCase   →  snake_case
 *       – every upper‑case letter (except the very first character) is
 *         preceded by an underscore.
 *       – upper‑case letters are converted to lower‑case.
 *
 * The program stores the result in a static buffer of 1024 bytes (including
 * the terminating NUL) and never writes past that limit.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <stddef.h>

#define OUTBUF_SIZE 1024          /* 0x400 bytes – matches the original binary */

static char main_out[OUTBUF_SIZE];   /* buffer used by the original program */

static void to_camel(const char *src)
{
    size_t out = 0;
    bool capitalize = false;

    for (size_t i = 0; src[i] != '\0'; ++i) {
        char c = src[i];

        if (c == '_') {                 /* skip underscores, remember to capitalize next */
            capitalize = true;
            continue;
        }

        if (capitalize) {
            if ('a' <= c && c <= 'z')
                c = (char)(c - 'a' + 'A');   /* make upper case */
            capitalize = false;
        } else {
            if ('A' <= c && c <= 'Z')
                c = (char)(c - 'A' + 'a');   /* force lower case */
        }

        if (out < OUTBUF_SIZE - 1)      /* keep space for terminating NUL */
            main_out[out++] = c;
    }

    main_out[out] = '\0';
    puts(main_out);
}

static void to_snake(const char *src)
{
    size_t out = 0;

    for (size_t i = 0; src[i] != '\0'; ++i) {
        char c = src[i];

        if ('A' <= c && c <= 'Z') {
            /* insert '_' before an upper‑case letter unless it is the first output char */
            if (out != 0 && out < OUTBUF_SIZE - 1)
                main_out[out++] = '_';

            c = (char)(c - 'A' + 'a');   /* lower‑case the letter */
        }

        if (out < OUTBUF_SIZE - 1)
            main_out[out++] = c;
    }

    main_out[out] = '\0';
    puts(main_out);
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
